				// Before record added
function BeforeAdd(&$values, &$message, $inline, &$pageObject)
{

		$values["monto"] = intval(round($values["monto"]));

if (empty(trim($values["nombre"]))) {
    $message = "El nombre del concepto es obligatorio.";
    return false;
}

if ($values["monto"] < 0) {
    $message = "El monto no puede ser negativo.";
    return false;
}

return true;
;		
} // function BeforeAdd

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
